DROP TRIGGER IF EXISTS `personinfo_insert_trigger`;
delimiter ;;
CREATE TRIGGER `personinfo_insert_trigger` AFTER INSERT ON `personinfo` FOR EACH ROW BEGIN
    -- 在 patientinfo 表中插入对应的记录
    VALUES (NEW.id, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
    
    -- 在 users 表中插入对应的记录
    VALUES (NEW.id, NULL, NULL);
END
;;
