delimiter ;;
CREATE TRIGGER `personinfo_update_trigger` AFTER UPDATE ON `personinfo` FOR EACH ROW BEGIN
    -- 在 patientinfo 表中更新对应的记录
    UPDATE patientinfo
    SET id = NEW.id
    WHERE id = OLD.id;
    
    -- 在 users 表中更新对应的记录
    UPDATE users
    SET id = NEW.id
    WHERE id = OLD.id;
END
;;
delimiter ;

